package adapters

import (
	"encoding/json"
	"os"
	"testing"
)

// Expected values were generated by Bun 1.4.0 Glob.match and acceptsEnvPath.
func TestBunGlobTable(t *testing.T) {
	data, err := os.ReadFile("testdata/bun-glob.json")
	if err != nil {
		t.Fatal(err)
	}
	var table struct {
		Glob []struct {
			Pattern, Path string
			Want          bool
		}
		Accept []struct {
			Path  string
			Rules EnvFileRules
			Want  bool
		}
	}
	if err := json.Unmarshal(data, &table); err != nil {
		t.Fatal(err)
	}
	for _, row := range table.Glob {
		if got := globMatch(row.Pattern, row.Path); got != row.Want {
			t.Errorf("glob %q %q: got %v want %v", row.Pattern, row.Path, got, row.Want)
		}
	}
	for _, row := range table.Accept {
		if got := AcceptsEnvPath(row.Path, row.Rules); got != row.Want {
			t.Errorf("accept %q %+v: got %v want %v", row.Path, row.Rules, got, row.Want)
		}
	}
}

func TestCheckEnvPathShortCircuitsPatterns(t *testing.T) {
	for _, row := range []struct {
		path    string
		rules   EnvFileRules
		want    bool
		invalid bool
	}{
		{".env", EnvFileRules{Include: []string{"[a]"}}, false, true},
		{".env", EnvFileRules{Exclude: []string{"[a]"}}, false, true},
		{".env", EnvFileRules{Include: []string{".env", "[a]"}}, true, false},
		{".env", EnvFileRules{Include: []string{}, Exclude: []string{"[a]"}}, false, false},
		{".envrc", EnvFileRules{Include: []string{"[a]"}}, false, false},
		{"node_modules/.env", EnvFileRules{Include: []string{"[a]"}}, false, false},
	} {
		got, err := CheckEnvPath(row.path, row.rules)
		if got != row.want || (err != nil) != row.invalid {
			t.Errorf("%s %+v: got %v, %v; want %v invalid=%v", row.path, row.rules, got, err, row.want, row.invalid)
		}
	}
}
